#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Al-othmany Sender 3.5.4 FINAL ALL-IN-ONE

Single upload patch.
- If source is 3.5.0 / 3.5.1 / 3.5.2, it first applies the complete 3.5.3 UI + Request/Join fix.
- If source is already 3.5.3, it keeps it and applies the 3.5.4 compact/continuity repair.
- If source is already 3.5.4, it verifies/finishes missing idempotent pieces.

Final: versionCode 354 / versionName 3.5.4.
"""
from pathlib import Path
import base64
import re
import traceback

ROOT = Path.cwd()
if not (ROOT / "app").is_dir():
    raise SystemExit("ERROR: run from the Android repository root")

BASE353 = ''
FIX354 = ''

def run_payload(label, payload):
    print("\n" + "="*72)
    print(label)
    print("="*72)
    source = base64.b64decode(payload).decode("utf-8")
    ns={"__name__":"__main__","__file__":f"<embedded:{label}>"}
    try:
        exec(compile(source, ns["__file__"], "exec"), ns, ns)
    except SystemExit:
        raise
    except Exception:
        traceback.print_exc()
        raise SystemExit(f"ERROR while applying {label}")

def version_code():
    s=(ROOT/'app/build.gradle.kts').read_text(encoding='utf-8')
    m=re.search(r'versionCode\s*=\s*(\d+)',s)
    return int(m.group(1)) if m else -1

vc=version_code()
if vc < 353:
    run_payload("STEP 1/2 - APPLY 3.5.3 COMPLETE UI + REQUEST/JOIN CORE", BASE353)
elif vc in (353,354):
    print(f"Source versionCode={vc}; base 3.5.3 stage not required.")
else:
    raise SystemExit(f"ERROR: unsupported future source versionCode={vc}")

run_payload("STEP 2/2 - APPLY 3.5.4 COMPACT LIGHTNING + CONTINUITY", FIX354)

s=(ROOT/'app/build.gradle.kts').read_text(encoding='utf-8')
required=[
    'versionCode = 354','versionName = "3.5.4"'
]
for token in required:
    if token not in s:
        raise SystemExit('ERROR: final version sanity missing '+token)

layout=(ROOT/'app/src/main/res/layout/activity_main.xml').read_text(encoding='utf-8')
acc=(ROOT/'app/src/main/java/com/althmany/groupmanager/accessibility/QuickJoinAccessibilityService.kt').read_text(encoding='utf-8')
main=(ROOT/'app/src/main/java/com/althmany/groupmanager/ui/MainActivity.kt').read_text(encoding='utf-8')
for token,src in [
    ('android:tag="compact354"',layout),
    ('exactStartButton',layout),
    ('ACCESSIBILITY_CONTROLLED_EXIT_HANDOFF',acc),
    ('Visible exact input and the hidden legacy engine input are a two-way bridge.',main),
]:
    if token not in src:
        raise SystemExit('ERROR: final 3.5.4 sanity missing '+token)

print("\n"+"="*72)
print("✅ AL-OTHMANY SENDER 3.5.4 FINAL ALL-IN-ONE APPLIED")
print("="*72)
print("Next:")
print("  python3 scripts/validate_source.py")
print("  bash scripts/compile_pure_kotlin.sh")
print("  bash scripts/run_pure_kotlin_regressions.sh")
print("  gradle --no-daemon --no-configuration-cache :app:assembleDebug --console=plain")
